In Swift, you can create a similar class using `CALayer` and `CATransform3D`. Here's an example:

```swift
import UIKit

class StackedLayers: CALayer {
    private var layers: [CALayer] = []
    private let iconScale: CGFloat = 0.7

    init(layers: [UIImage], iconScale: CGFloat = 0.7) {
        super.init()
        self.layers = layers.map { image in
            let layer = CALayer()
            let imageView = UIImageView(image: image)
            imageView.contentMode = .scaleAspectFit
            imageView.frame = bounds
            addSublayer(layer)
            layer.contents = imageView.layer
            return layer
        }
        self.iconScale = iconScale
    }

    override func layoutSublayers() {
        super.layoutSublayers()
        let newWidth = bounds.width
        let iconsSize = floor(newWidth * iconScale)
        let iconsInset = (newWidth - iconsSize) - 1

        for (index, layer) in layers.enumerated() {
            layer.frame = CGRect(x: iconsInset, y: iconsInset, width: iconsSize, height: iconsSize)
            layer.position = CGPoint(x: bounds.midX, y: bounds.midY)

            let transform: CATransform3D
            switch index {
            case 1:
                transform = CATransform3DMakeTranslation(0, iconsInset, 0)
            case 0:
                transform = CATransform3DMakeTranslation(iconsInset, 0, 0)
            default:
                transform = CATransform3DIdentity
            }
            layer.transform = transform
        }
    }
}
```

