```javascript
function mergeArrays(arr1, arr2) {
  const merged = [];
  const uniqueIds = new Set();

  // Iterate through the first array
  arr1.forEach(obj => {
    const id = `${obj.stepId}-${obj.fieldId}`;

    // If the object is unique, add it to the merged array
    if (!uniqueIds.has(id)) {
      uniqueIds.add(id);
      merged.push(obj);
    }
  });

  // Iterate through the second array and merge objects if necessary
  arr2.forEach(obj => {
    const id = `${obj.stepId}-${obj.fieldId}`;

    // If the object is already in the merged array, merge it with the existing object
    if (merged.some(mObj => mObj.stepId === obj.stepId && mObj.fieldId === obj.fieldId)) {
      merged.forEach(mObj => {
        if (mObj.message === undefined) {
          mObj.message = obj.message;
        }
      });
    } else {
      // If the object is not in the merged array, add it
      uniqueIds.add(id);
      merged.push(obj);
    }
  });

  return merged;
}

