```

4. Open the `src/block.js` file and replace its content with the following code:

```javascript
const { registerBlockType } = wp.blocks;
const { RichText, MediaUpload, InspectorControls } = wp.editor;
const { Button } = wp.components;

registerBlockType( 'my-plugin/my-custom-block', {
    title: 'My Custom Block',
    icon: 'smiley',
    category: 'common',
    attributes: {
        title: {
            type: 'string',
            source: 'html',
            selector: 'h2',
        },
        content: {
            type: 'string',
            source: 'html',
            selector: 'p',
        },
        imageAlt: {
            attribute: 'alt',
            selector: '.my-image',
        },
        imageUrl: {
            attribute: 'src',
            selector: '.my-image',
        },
    },
    edit({ attributes, setAttributes }) {
        const handleMediaUpload = (image) => {
            setAttributes({ imageUrl: image.url, imageAlt: image.alt });
        };

        return (
            <div className="my-custom-block">
                <InspectorControls key="inspector">
                    <Button
                        onClick={ () => handleMediaUpload( false ) }
                        className="button button-large"
                    >
                        Upload Image
                    </Button>
                </InspectorControls>
                <div>
                    <RichText
                        tagName="h2"
                        value={ attributes.title }
                        onChange={ ( value ) => setAttributes( { title: value } ) }
                    />
                    <RichText
                        tagName="p"
                        value={ attributes.content }
                        onChange={ ( value ) => setAttributes( { content: value } ) }
                    />
                    { attributes.imageUrl && (
                        <img
                            src={ attributes.imageUrl }
                            alt={ attributes.imageAlt }
                            className="my-image"
                        />
                    ) }
                    { ! attributes.imageUrl && (
                        <MediaUpload
                            onSelect={ handleMediaUpload }
                            type="image"
                            value={ attributes.imageId }
                            render={ ({ open }) => (
                                <Button onClick={ open }>
                                    Select Image
                                </Button>
                            ) }
                        />
                    ) }
                </div>
            </div>
        );
    },
    save({ attributes }) {
        const { title, content, imageUrl, imageAlt } = attributes;

        return (
            <div className="my-custom-block">
                { title && <h2>{ title }</h2> }
                { content && <p>{ content }</p> }
                { imageUrl && <img src={ imageUrl } alt={ imageAlt } /> }
            </div>
        );
    },
});
```

